import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 8.0
.target sm_89
.address_size 64

.visible .entry convt3d_kernel(
    .param .u64 p_input,
    .param .u64 p_weight,
    .param .u64 p_output,
    .param .u32 pN,
    .param .u32 pCin,
    .param .u32 pCout,
    .param .u32 pDin,
    .param .u32 pHin,
    .param .u32 pWin,
    .param .u32 pKd,
    .param .u32 pKh,
    .param .u32 pKw,
    .param .u32 pDout,
    .param .u32 pHout,
    .param .u32 pWout
)
{
    .reg .pred  %p<16>;
    .reg .b32   %r<80>;
    .reg .b64   %rd<40>;
    .reg .f32   %f<8>;

    // Load params
    ld.param.u64    %rd10, [p_input];
    ld.param.u64    %rd11, [p_weight];
    ld.param.u64    %rd12, [p_output];

    ld.param.u32    %r10, [pN];
    ld.param.u32    %r11, [pCin];
    ld.param.u32    %r12, [pCout];
    ld.param.u32    %r13, [pDin];
    ld.param.u32    %r14, [pHin];
    ld.param.u32    %r15, [pWin];
    ld.param.u32    %r16, [pKd];
    ld.param.u32    %r17, [pKh];
    ld.param.u32    %r18, [pKw];
    ld.param.u32    %r19, [pDout];
    ld.param.u32    %r20, [pHout];
    ld.param.u32    %r21, [pWout];

    // Compute linear thread id gid = blockIdx.x * blockDim.x + threadIdx.x
    mov.u32         %r30, %tid.x;
    mov.u32         %r31, %ntid.x;
    mov.u32         %r32, %ctaid.x;
    mad.lo.s32      %r33, %r32, %r31, %r30; // gid

    // Compute total output elements: N * Cout * Dout * Hout * Wout
    mul.lo.u32      %r40, %r10, %r12;      // N*Cout
    mul.lo.u32      %r41, %r19, %r20;      // Dout*Hout
    mul.lo.u32      %r42, %r41, %r21;      // Dout*Hout*Wout
    mul.lo.u32      %r43, %r40, %r42;      // total

    setp.ge.u32     %p0, %r33, %r43;
    @%p0 bra        RET; // out of bounds thread

    // Decode gid into (n, oc, zo, yo, xo)
    // xo = gid % Wout; t = gid / Wout;
    rem.u32         %r50, %r33, %r21;      // xo
    div.u32         %r51, %r33, %r21;      // t1

    rem.u32         %r52, %r51, %r20;      // yo
    div.u32         %r53, %r51, %r20;      // t2

    rem.u32         %r54, %r53, %r19;      // zo
    div.u32         %r55, %r53, %r19;      // t3

    rem.u32         %r56, %r55, %r12;      // oc
    div.u32         %r57, %r55, %r12;      // n

    // Prepare output address: out_ptr + gid * 4
    mul.wide.u32    %rd20, %r33, 4;
    add.s64         %rd21, %rd12, %rd20;

    // Accumulator
    mov.f32         %f0, 0f00000000;

    // Loop over ic
    mov.u32         %r60, 0;               // ic = 0
L_ic:
    setp.ge.u32     %p1, %r60, %r11;
    @%p1 bra        L_ic_end;

    // Loop over kz
    mov.u32         %r61, 0;               // kz = 0
L_kz:
    setp.ge.u32     %p2, %r61, %r16;
    @%p2 bra        L_kz_end;

    // zi = zo - kz
    sub.s32         %r62, %r54, %r61;
    setp.lt.s32     %p3, %r62, 0;
    setp.ge.s32     %p4, %r62, %r13;
    or.pred         %p5, %p3, %p4;
    @%p5 bra        L_kz_next;

    // Loop over ky
    mov.u32         %r63, 0;               // ky = 0
L_ky:
    setp.ge.u32     %p6, %r63, %r17;
    @%p6 bra        L_ky_end;

    // yi = yo - ky
    sub.s32         %r64, %r52, %r63;
    setp.lt.s32     %p7, %r64, 0;
    setp.ge.s32     %p8, %r64, %r14;
    or.pred         %p9, %p7, %p8;
    @%p9 bra        L_ky_next;

    // Loop over kx
    mov.u32         %r65, 0;               // kx = 0
L_kx:
    setp.ge.u32     %p10, %r65, %r18;
    @%p10 bra       L_kx_end;

    // xi = xo - kx
    sub.s32         %r66, %r50, %r65;
    setp.lt.s32     %p11, %r66, 0;
    setp.ge.s32     %p12, %r66, %r15;
    or.pred         %p13, %p11, %p12;
    @%p13 bra       L_kx_next;

    // Compute input index: (((((n*Cin + ic)*Din + zi)*Hin + yi)*Win + xi))
    // t = n*Cin + ic
    mul.lo.u32      %r70, %r57, %r11;
    add.u32         %r70, %r70, %r60;
    // t = t*Din + zi
    mad.lo.u32      %r70, %r70, %r13, %r62;
    // t = t*Hin + yi
    mad.lo.u32      %r70, %r70, %r14, %r64;
    // t = t*Win + xi
    mad.lo.u32      %r70, %r70, %r15, %r66;

    // Compute weight index: (((((ic*Cout + oc)*Kd + kz)*Kh + ky)*Kw + kx))
    mul.lo.u32      %r71, %r60, %r12;
    add.u32         %r71, %r71, %r56;
    mad.lo.u32      %r71, %r71, %r16, %r61;
    mad.lo.u32      %r71, %r71, %r17, %r63;
    mad.lo.u32      %r71, %r71, %r18, %r65;

    // Load input and weight
    mul.wide.u32    %rd30, %r70, 4;
    add.s64         %rd31, %rd10, %rd30;
    ld.global.f32   %f1, [%rd31];

    mul.wide.u32    %rd32, %r71, 4;
    add.s64         %rd33, %rd11, %rd32;
    ld.global.f32   %f2, [%rd33];

    // FMA accumulate
    fma.rn.f32      %f0, %f1, %f2, %f0;

L_kx_next:
    add.u32         %r65, %r65, 1;
    bra             L_kx;
L_kx_end:

L_ky_next:
    add.u32         %r63, %r63, 1;
    bra             L_ky;
L_ky_end:

L_kz_next:
    add.u32         %r61, %r61, 1;
    bra             L_kz;
L_kz_end:

    add.u32         %r60, %r60, 1;
    bra             L_ic;
L_ic_end:

    // Store result
    st.global.f32   [%rd21], %f0;

RET:
    ret;
}
"""

_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("convt3d_kernel")

class ModelNew(nn.Module):
    def __init__(self, in_channels: int, out_channels: int, kernel_size: tuple, stride: tuple = (1, 1, 1), padding: tuple = (0, 0, 0), output_padding: tuple = (0, 0, 0), groups: int = 1, bias: bool = False):
        super().__init__()
        if groups != 1:
            raise NotImplementedError("groups != 1 not supported")
        if stride != (1, 1, 1):
            raise NotImplementedError("Only stride=(1,1,1) supported")
        if padding != (0, 0, 0):
            raise NotImplementedError("Only padding=(0,0,0) supported")
        if output_padding != (0, 0, 0):
            raise NotImplementedError("Only output_padding=(0,0,0) supported")
        if bias:
            raise NotImplementedError("bias=True not supported")
        kd, kh, kw = kernel_size
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = (kd, kh, kw)
        self.stride = stride
        self.padding = padding
        self.output_padding = output_padding
        self.groups = groups
        self.bias = None
        # Weight layout matches nn.ConvTranspose3d: (in_channels, out_channels, kd, kh, kw)
        w = torch.empty(in_channels, out_channels, kd, kh, kw)
        nn.init.kaiming_uniform_(w, a=5 ** 0.5)
        self.weight = nn.Parameter(w)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        if not x.is_cuda:
            raise RuntimeError("Input must be a CUDA tensor")
        if x.dtype != torch.float32:
